}
.title-main h1::after {
  content: "ORBITAL";
  position: absolute;
  inset: 0;
  color: transparent;
  -webkit-text-stroke: 1px rgba(95,245,224,.14);
  transform: translate(7px, 7px);
  z-index: -1;
  letter-spacing: .11em;
}
.title-sub {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 16px;
  font-family: var(--mono);
  font-size: clamp(14px, 2.1vw, 27px);
  font-weight: 400;
