}
.tagline b { color: #d7f6f0; font-weight: 500; }
.start-row {
  display: flex;
  align-items: center;
  gap: 22px;
  margin-top: 34px;
  flex-wrap: wrap;
}
.start-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
