  overflow: hidden;
}
.start-btn:hover { background: #93fff3; box-shadow: 0 0 60px rgba(95,245,224,.3); }
.start-btn:active { transform: scale(.98); }
.start-btn .start-ico { font-size: 11px; letter-spacing: 0; }
.start-btn .start-bar {
  position: absolute;
  left: 0; bottom: 0;
  height: 3px;
  width: 38%;
  background: #01100f;
  opacity: .22;
}
.start-btn.small { min-width: 180px; height: 48px; font-size: 12px; }
.start-note {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .14em;
  color: var(--ink-faint);
  line-height: 1.4;
}
.start-note span:first-child { color: var(--ink-dim); }
.title-foot {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 30px;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .12em;
  color: var(--ink-faint);
}
.title-foot .sep { opacity: .45; }

.brief-card {
  position: relative;
  flex: 0 0 clamp(300px, 27vw, 374px);
  padding: 20px 20px 18px;
  background: linear-gradient(160deg, rgba(4, 19, 22, .76), rgba(2, 9, 11, .66));
  border: 1px solid rgba(95,245,224,.2);
  backdrop-filter: blur(7px);
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 0 100%);
  align-self: center;
}
.brief-card::before {
  content: "";
  position: absolute;
  top: 0; left: 0;
  width: 56px; height: 1px;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
}
.brief-head {
  display: flex;
  justify-content: space-between;
  gap: 10px;
