/* ============================================================
   FLASH / ROTATE HINT
   ============================================================ */
.flash {
  position: absolute;
  inset: 0;
  z-index: 25;
  background: radial-gradient(circle, rgba(95,245,224,.28), transparent 65%);
  opacity: 0;
  pointer-events: none;
}
.flash.fire { animation: flashFire .6s ease-out; }
@keyframes flashFire {
  0% { opacity: 0; }
  18% { opacity: 1; }
