/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1100px) {
  .op-block { display: none; }
  .brief-card { flex-basis: 310px; }
}
@media (max-width: 900px) {
  :root { --panel-w: 360px; }
