  }
  .trace-top { display: flex; align-items: baseline; gap: 4px; flex: 0 0 auto; }
  .trace-track { flex: 1; width: auto; }
  .trace-pct { display: none; }
  .spoof { height: 30px; padding: 0 8px; }
  .spoof-text b { font-size: 8px; }
  .spoof-text small { font-size: 6.5px; }
