  .top-actions { margin-left: auto; }
  .icon-btn { width: 32px; height: 32px; }
  .intel-cluster { top: calc(102px + var(--safe-top)); left: calc(14px + var(--safe-left)); }
  .panel {
    top: auto;
    bottom: 0;
    right: 0;
    left: 0;
