  .breach-grid { gap: 3px; margin: 7px 0; }
  .cell { min-height: 34px; font-size: 15px; }
  .proto-cell { width: 24px; height: 24px; font-size: 12px; }
  .proto-wrap { padding: 6px 0; }
  .breach-timer-top { margin-bottom: 3px; }
  .secured-copy { font-size: 10.5px; }
  .coach {
    bottom: calc(14px + var(--safe-bottom));
    font-size: 8px;
    padding: 7px 10px;
    max-width: 88vw;
    letter-spacing: .1em;
  }
  .hud-help { display: none; }
  .markers .marker { padding: 3px 5px; font-size: 8px; gap: 4px; }
  .marker .m-name { font-size: 8px; }
  .marker.captured .m-sub { display: none; }
  .counter-alert {
    top: calc(96px + var(--safe-top));
    min-width: 0;
    width: calc(100% - 24px - var(--safe-left) - var(--safe-right));
