  .purge-btn { padding: 6px 10px; font-size: 9px; }
  .toasts { top: calc(126px + var(--safe-top)); }
  .toast { font-size: 8px; padding: 6px 10px; }

  /* Title mobile */
  .title-topline { padding: calc(14px + var(--safe-top)) calc(16px + var(--safe-right)) 0 calc(16px + var(--safe-left)); font-size: 6.5px; }
  .title-topline span:first-child { display: none; }
  .title-grid { padding: 12px calc(16px + var(--safe-right)) calc(20px + var(--safe-bottom)) calc(16px + var(--safe-left)); gap: 20px; justify-content: flex-end; }
  .kicker { font-size: 7px; letter-spacing: .1em; margin-bottom: 10px; }
  .title-main h1 { font-size: clamp(48px, 16.5vw, 84px); }
  .title-sub { font-size: clamp(11px, 3.4vw, 16px); letter-spacing: .18em; gap: 8px; }
  .title-sub::before { width: 20px; }
  .tagline { font-size: 11.5px; margin-top: 14px; line-height: 1.5; }
  .start-row { margin-top: 18px; gap: 14px; }
  .start-btn { min-width: 180px; height: 52px; font-size: 13px; }
