Fragment:
```glsl
precision highp float;
uniform vec3 uSun;
uniform float uTime;
varying vec3 vPos;
varying vec3 vNormalW;
varying vec3 vView;

float hash(vec3 p) { ... }
...
void main(){
  vec3 p = normalize(vPos);
  vec3 n = normalize(vNormalW);
  float h = fbm(p * 2.45 + vec3(7.1));
  float detail = fbm(p * 6.4 + vec3(2.7));
  float landMask = smoothstep(0.49, 0.55, h + detail * 0.08);
  // continental shelf
  float shelf = smoothstep(0.44, 0.50, h + detail*0.08);
  float ice = smoothstep(0.82, 0.93, abs(p.y) + (detail-0.5)*0.12);

  vec3 deep = vec3(0.008, 0.036, 0.07);
  vec3 shallow = vec3(0.018, 0.115, 0.145);
  vec3 ocean = mix(deep, shallow, shelf);

  float elev = smoothstep(0.50, 0.70, h*0.6 + detail*0.55);
  vec3 lowland = vec3(0.075, 0.13, 0.095);
  vec3 highland = vec3(0.21, 0.19, 0.13);
  vec3 desert = vec3(0.30, 0.24, 0.14);
  float arid = smoothstep(0.52,0.72, fbm(p*3.9 + 11.0));
  vec3 landCol = mix(lowland, highland, elev);
  landCol = mix(landCol, desert, arid*0.55);
  landCol = mix(landCol, vec3(0.52,0.56,0.52), ice*0.9);

  vec3 albedo = mix(ocean, landCol, landMask);
  albedo = mix(albedo, vec3(0.78,0.88,0.9), ice);

  float day = smoothstep(-0.16, 0.32, dot(n, uSun));
  float rim = pow(1.0 - max(dot(n, normalize(vView)), 0.0), 2.6);
  vec3 col = albedo * (0.06 + day * 1.15);
  col += vec3(0.09,0.35,0.38) * rim * (0.25 + day*0.5);

  // city lights
  float cityNoise = fbm(p*26.0 + vec3(3.0));
  float city = smoothstep(0.56, 0.68, cityNoise) * landMask * (1.0 - day) * (1.0 - ice);
  city *= smoothstep(0.0,0.2, 1.0 - abs(p.y));
  vec3 cityCol = vec3(1.0, 0.62, 0.28) * city * 0.85;
  col += cityCol;

  // subtle day-side atmospheric scatter
  col += vec3(0.05,0.16,0.2) * pow(max(dot(n, uSun),0.0),2.0) * 0.15;
  // ocean glint
  vec3 viewDir = normalize(vView);
  vec3 hVec = normalize(uSun + viewDir);
  float spec = pow(max(dot(n,hVec),0.0), 60.0) * (1.0-landMask) * day;
  col += vec3(0.5,0.7,0.8) * spec * 0.3;

  gl_FragColor = vec4(col, 1.0);
}
```
