function orbitBasis(incDeg, raanDeg){
 const inc = deg2rad(incDeg), raan = deg2rad(raanDeg);
 const normal = new THREE.Vector3(Math.sin(inc)*Math.sin(raan), Math.cos(inc), Math.sin(inc)*Math.cos(raan)).normalize();
 const u = new THREE.Vector3(Math.cos(raan), 0, -Math.sin(raan)); // node line
 const v = new THREE.Vector3().crossVectors(normal, u); // ensure unit
 return {u,v,normal};
}
