```js
function satPosAt(sat, theta){ return sat.u.clone().multiplyScalar(Math.cos(theta)).addScaledVector(sat.v, Math.sin(theta)).multiplyScalar(sat.radius); }
function elevationAt(sat, theta){ const p = satPosAt(sat, theta).normalize(); return Math.asin(clamp(p.dot(STATION_DIR),-1,1))*180/Math.PI; }
function predictCross(sat, threshold=4){
  // if currently above, find next time below; else next above
  const above = sat.elevation > threshold;
  let theta = sat.theta;
  const step = 0.015; // rad
  for (let s=1; s<=600; s++) {
    theta += step;
    const el = elevationAt(sat, theta);
    if (above && el < threshold) return s*step/sat.speed;
    if (!above && el > threshold) return s*step/sat.speed;
  }
  return null;
}
```
