import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { createRequire } from 'node:module'
import { startForCapture } from '/home/runner/work/_temp/omgithub-runtime/scripts/capture-start.mjs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true })
page.on('pageerror', e => console.log('PAGEERROR', e.message))
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()) })

const state = () => page.evaluate(() => ({
  phaseEnd: !document.getElementById('endScreen').hidden,
  endTitle: document.getElementById('endTitle').textContent,
  panelOpen: document.body.classList.contains('panel-open'),
  panelName: document.getElementById('panelName').textContent,
  hook: !!document.getElementById('hookView').offsetParent,
  breach: !!document.getElementById('breachView').offsetParent,
  secured: !!document.getElementById('securedView').offsetParent,
  counter: !document.getElementById('counterAlert').hidden,
  trace: document.getElementById('tracePct').textContent,
  intel: document.getElementById('intelCount').textContent,
  lockDisabled: document.getElementById('lockBtn').disabled,
  needle: parseFloat(document.getElementById('freqNeedle').style.left || '-1'),
  zoneL: parseFloat(document.getElementById('freqZone').style.left || '-1'),
  zoneW: parseFloat(document.getElementById('freqZone').style.width || '-1'),
  chips: [...document.querySelectorAll('.rail-chip')].map(c => c.textContent.replace(/\s+/g, ' ').trim()),
  pause: !document.getElementById('pauseScreen').hidden,
  help: !document.getElementById('helpScreen').hidden,
}))

async function maybePurge(tag) {
  if (await page.locator('#counterAlert').isVisible()) {
    console.log('COUNTER ALERT at', tag, await page.locator('#purgeTimer').textContent())
    await page.screenshot({ path: '/tmp/opencode/mcounter.jpg', type: 'jpeg', quality: 82 })
    await page.locator('#purgeBtn').click()
    console.log('PURGED')
  }
}

async function hookAndBreach(name) {
  console.log('--- TARGET', name)
  await page.locator('.rail-chip', { hasText: name }).click()
  await page.waitForTimeout(250)
  if (!(await page.locator('#panel').isVisible())) throw new Error('panel did not open for ' + name)
  const deadline = Date.now() + 45000
  while (Date.now() < deadline) {
    await maybePurge(name)
    const s = await state()
    if (s.secured) {
      console.log('SECURED VIEW', s.panelName, 'trace', s.trace, 'intel', s.intel)
      return true
    }
    if (s.breach) {
      // Solve every layer synchronously through the real UI handlers.
      const solved = await page.evaluate(() => {
        let guard = 0
        while (guard++ < 80) {
          const cur = document.querySelector('#protoRow .proto-cell.current')
          if (!cur) return { ok: false, reason: 'no-current' }
          const glyph = cur.textContent
          const btn = [...document.querySelectorAll('#breachGrid .cell')].find(b => b.dataset.glyph === glyph)
          if (!btn) return { ok: false, reason: 'no-cell', glyph }
          btn.click()
          if (!document.getElementById('breachView').offsetParent) return { ok: true, steps: guard }
        }
        return { ok: false, reason: 'guard' }
      })
      console.log('BREACH', solved)
      await page.waitForTimeout(300)
      await maybePurge(name + ' post-breach')
      continue
    }
    if (s.hook) {
      if (!s.lockDisabled && s.needle >= s.zoneL && s.needle <= s.zoneL + s.zoneW) {
        await page.locator('#lockBtn').click()
        await page.waitForTimeout(80)
      } else {
        await page.waitForTimeout(24)
      }
      continue
    }
    await page.waitForTimeout(120)
  }
  throw new Error('timed out on ' + name)
}

await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForTimeout(900)
console.log('START', await startForCapture(page, { enabled: true }))
await page.waitForTimeout(900)

// Pause / resume check
await page.locator('#pauseBtn').click()
await page.waitForTimeout(250)
console.log('PAUSE', (await state()).pause)
await page.screenshot({ path: '/tmp/opencode/mpause.jpg', type: 'jpeg', quality: 82 })
await page.locator('#resumeBtn').click()
await page.waitForTimeout(300)
console.log('RESUMED', !(await state()).pause)

// Help check (keyboard H)
await page.keyboard.press('KeyH')
await page.waitForTimeout(250)
console.log('HELP', (await state()).help)
await page.screenshot({ path: '/tmp/opencode/mhelp.jpg', type: 'jpeg', quality: 82 })
await page.locator('#helpClose').click()
await page.waitForTimeout(300)

const order = ['ARGUS-7', 'VESPER-2', 'HELIOS-9', 'KESTREL-1']
for (const name of order) {
  const s = await state()
  const chip = s.chips.find(c => c.startsWith(name))
  if (!chip || !chip.includes('EL')) {
    console.log('SKIP below horizon', name, chip)
    continue
  }
  await hookAndBreach(name)
  // Close secured view and return to orbit.
  if (await page.locator('#securedView').isVisible()) {
    if ((await state()).intel === '1') {
      await page.screenshot({ path: '/tmp/opencode/msecured.jpg', type: 'jpeg', quality: 82 })
    }
    await page.locator('#securedClose').click()
    await page.waitForTimeout(350)
  }
  const st = await state()
  console.log('AFTER TARGET', name, 'intel', st.intel, 'trace', st.trace, 'end', st.phaseEnd)
  if (st.intel === '4') break
}

// Wait for the win screen (2.8s countdown).
await page.waitForTimeout(3400)
let win = await state()
console.log('WIN STATE', win)
if (win.phaseEnd) {
  console.log('WIN STATS', await page.evaluate(() => ({
    title: document.getElementById('endTitle').textContent,
    kicker: document.getElementById('endKicker').textContent,
    intel: document.getElementById('statIntel').textContent,
    time: document.getElementById('statTime').textContent,
    trace: document.getElementById('statTrace').textContent,
    score: document.getElementById('statScore').textContent,
    sats: document.getElementById('endSats').children.length,
  })))
  await page.screenshot({ path: '/tmp/opencode/mwin.jpg', type: 'jpeg', quality: 82 })
}

// Restart and force a loss by spamming wrong protocol glyphs.
await page.locator('#redeployBtn').click()
await page.waitForTimeout(700)
console.log('REDEPLOY', await state())
await page.locator('.rail-chip', { hasText: 'ARGUS-7' }).click()
await page.waitForTimeout(250)
const deadline = Date.now() + 25000
while (Date.now() < deadline) {
  const s = await state()
  if (s.breach) break
  if (s.hook && !s.lockDisabled && s.needle >= s.zoneL && s.needle <= s.zoneL + s.zoneW) {
    await page.locator('#lockBtn').click()
  }
  await page.waitForTimeout(22)
}
const bad = await page.evaluate(() => {
  const cur = document.querySelector('#protoRow .proto-cell.current')
  if (!cur) return { ok: false }
  const glyph = cur.textContent
  const btn = [...document.querySelectorAll('#breachGrid .cell')].find(b => b.dataset.glyph !== glyph)
  if (!btn) return { ok: false }
  for (let i = 0; i < 90; i++) btn.click()
  return { ok: true, trace: document.getElementById('tracePct').textContent }
})
console.log('LOSS SPAM', bad)
await page.waitForTimeout(600)
const lost = await state()
console.log('LOST STATE', lost)
if (lost.phaseEnd) {
  console.log('LOSE STATS', await page.evaluate(() => ({
    title: document.getElementById('endTitle').textContent,
    kicker: document.getElementById('endKicker').textContent,
    copy: document.getElementById('endCopy').textContent,
    score: document.getElementById('statScore').textContent,
  })))
  await page.screenshot({ path: '/tmp/opencode/mlose.jpg', type: 'jpeg', quality: 82 })
}
await browser.close()

