import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { createRequire } from 'node:module'
import { startForCapture } from '/home/runner/work/_temp/omgithub-runtime/scripts/capture-start.mjs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true })
page.on('pageerror', e => console.log('PAGEERROR', e.message))
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()) })

const state = () => page.evaluate(() => ({
  phaseEnd: !document.getElementById('endScreen').hidden,
  endTitle: document.getElementById('endTitle').textContent,
  panelOpen: document.body.classList.contains('panel-open'),
  panelName: document.getElementById('panelName').textContent,
  hook: !document.getElementById('hookView').hidden && document.getElementById('panel').getAttribute('aria-hidden') === 'false',
  breach: !document.getElementById('breachView').hidden && document.getElementById('panel').getAttribute('aria-hidden') === 'false',
  secured: !document.getElementById('securedView').hidden && document.getElementById('panel').getAttribute('aria-hidden') === 'false',
  counter: !document.getElementById('counterAlert').hidden,
  trace: document.getElementById('tracePct').textContent,
  intel: document.getElementById('intelCount').textContent,
  lockDisabled: document.getElementById('lockBtn').disabled,
  needle: parseFloat(document.getElementById('freqNeedle').style.left || '-1'),
  zoneL: parseFloat(document.getElementById('freqZone').style.left || '-1'),
  zoneW: parseFloat(document.getElementById('freqZone').style.width || '-1'),
  chips: [...document.querySelectorAll('.rail-chip')].map(c => c.textContent.replace(/\s+/g, ' ').trim()),
}))

async function hookAndBreach(name) {
  console.log('--- TARGET', name)
  await page.locator('.rail-chip', { hasText: name }).click()
  await page.waitForFunction(n => (
    document.getElementById('panelName').textContent === n &&
    document.getElementById('panel').getAttribute('aria-hidden') === 'false'
  ), name, { timeout: 5000 })
  await page.waitForTimeout(150)
  const deadline = Date.now() + 45000
  while (Date.now() < deadline) {
    if (await page.evaluate(() => !document.getElementById('counterAlert').hidden)) {
      await page.evaluate(() => document.getElementById('purgeBtn').click())
      console.log('purged mid-hack')
    }
    const s = await state()
    if (s.secured) return true
    if (s.breach) {
      const solved = await page.evaluate(() => {
        let guard = 0
        while (guard++ < 80) {
          const cur = document.querySelector('#protoRow .proto-cell.current')
          if (!cur) return { ok: false, reason: 'no-current' }
          const btn = [...document.querySelectorAll('#breachGrid .cell')].find(b => b.dataset.glyph === cur.textContent)
          if (!btn) return { ok: false, reason: 'no-cell' }
          btn.click()
          if (!document.getElementById('breachView').offsetParent) return { ok: true, steps: guard }
        }
        return { ok: false, reason: 'guard' }
      })
      console.log('BREACH', solved)
      await page.waitForTimeout(250)
      continue
    }
    if (s.hook) {
      if (!s.lockDisabled && s.needle >= s.zoneL && s.needle <= s.zoneL + s.zoneW) {
        await page.evaluate(() => document.getElementById('lockBtn').click())
      }
      await page.waitForTimeout(20)
      continue
    }
    await page.waitForTimeout(100)
  }
  throw new Error('timed out on ' + name)
}

await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForTimeout(700)
await startForCapture(page, { enabled: true })
await page.waitForTimeout(700)

// Win a full operation.
for (const name of ['ARGUS-7', 'VESPER-2', 'HELIOS-9', 'KESTREL-1']) {
  await hookAndBreach(name)
  const st = await state()
  console.log('CAPTURED', name, 'intel', st.intel, 'trace', st.trace)
  if (st.intel === '4') break
  await page.evaluate(() => document.getElementById('securedClose').click())
  await page.waitForTimeout(200)
}
console.log('WAITING FOR WIN SCREEN', await state())
await page.waitForSelector('#endScreen:not([hidden])', { state: 'visible', timeout: 25000 })
await page.waitForTimeout(500)
console.log('WIN', await page.evaluate(() => ({
  title: document.getElementById('endTitle').textContent,
  kicker: document.getElementById('endKicker').textContent,
  intel: document.getElementById('statIntel').textContent,
  time: document.getElementById('statTime').textContent,
  trace: document.getElementById('statTrace').textContent,
  score: document.getElementById('statScore').textContent,
  sats: document.getElementById('endSats').children.length,
  note: document.querySelector('.end-note').textContent,
})))
await page.screenshot({ path: '/tmp/opencode/mwin.jpg', type: 'jpeg', quality: 82 })

// Redeploy and wait for the first counter sweep.
await page.evaluate(() => document.getElementById('redeployBtn').click())
await page.waitForTimeout(900)
console.log('REDEPLOYED', await state())
const t0 = Date.now()
await page.waitForSelector('#counterAlert:not([hidden])', { state: 'visible', timeout: 70000 })
console.log('COUNTER #1 after', ((Date.now() - t0) / 1000).toFixed(1), 's wall; trace', await page.locator('#tracePct').textContent())
await page.waitForTimeout(400)
await page.screenshot({ path: '/tmp/opencode/mcounter.jpg', type: 'jpeg', quality: 82 })
const traceBefore = parseFloat(await page.locator('#tracePct').textContent())
await page.evaluate(() => document.getElementById('purgeBtn').click())
await page.waitForTimeout(500)
console.log('PURGE', { before: traceBefore, after: parseFloat(await page.locator('#tracePct').textContent()), hidden: await page.evaluate(() => document.getElementById('counterAlert').hidden) })

// Wait for the next sweep, miss it on purpose, capture the trace spike.
const t1 = Date.now()
await page.waitForSelector('#counterAlert:not([hidden])', { state: 'visible', timeout: 70000 })
console.log('COUNTER #2 after', ((Date.now() - t1) / 1000).toFixed(1), 's wall; trace', await page.locator('#tracePct').textContent())
const beforeMiss = parseFloat(await page.locator('#tracePct').textContent())
await page.waitForTimeout(6600)
const afterMiss = parseFloat(await page.locator('#tracePct').textContent())
console.log('MISS', { before: beforeMiss, after: afterMiss, hidden: await page.evaluate(() => document.getElementById('counterAlert').hidden) })
await page.screenshot({ path: '/tmp/opencode/mcounter-miss.jpg', type: 'jpeg', quality: 82 })
await browser.close()

